RustPythonNode.jsWASM <p><code>adaptivemsw</code> exposes 1 optional output: <code>dc_period</code>. Pass a boolean mask as the third argument — one <code>bool</code> per optional output, in order.</p> <pre><code>use tulip_rs::indicators::adaptivemsw::{AdaptiveMSW, Indicator, TIndicatorState};

let close = vec![81.59, 81.06, 82.87, 83.00, 83.61, 83.15, 82.84, 83.99, 84.55, 84.36,
                 85.53, 86.54, 86.89, 87.77, 87.29, 87.50, 88.10, 88.50, 87.90, 88.20,
                 88.80, 89.10, 88.70, 89.30, 89.70, 90.10, 89.50, 90.20, 90.80, 91.10,
                 90.50, 91.20, 91.80, 92.10, 91.50, 92.20, 92.80, 93.10, 92.50, 93.20_f64];

let mask = [true]; // one per optional output
